def hidden_rule_fn(state):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    n = len(state)  # index of new element
    a = state[-2]
    b = state[-1]

    if is_prime(n):
        new_val = (a ^ b) % 7  # ploon-XOR
    else:
        new_val = (a + b + 3) % 7  # grolp-sum

    return state + [new_val]
